package com.everettjf.scriptwidget.core.runtime

import android.content.Context
import org.json.JSONObject
import java.util.concurrent.ConcurrentHashMap

/** JavaScript assets generated by `Android/scripts/build-shared-js.mjs`. */
class SharedScripts(context: Context) {
    private val assets = context.applicationContext.assets
    private val cache = ConcurrentHashMap<String, String>()

    fun text(name: String): String = cache.getOrPut(name) {
        assets.open("scriptwidget/$name").use { it.readBytes().toString(Charsets.UTF_8) }
    }

    /** Host files evaluated before the kernel, in order. */
    val hostFiles: List<String> by lazy {
        (assets.list("scriptwidget") ?: emptyArray())
            .filter { it.startsWith("android-") && it.endsWith(".js") && it != "android-compiler.js" }
            .sorted()
    }

    val contract: JSONObject by lazy { JSONObject(text("contract.json")).getJSONObject("contract") }
    val errorCategories: JSONObject by lazy { JSONObject(text("contract.json")).getJSONObject("errorCategories") }

    fun supportScript(name: String): String? = when (name) {
        "util.js", "moment.min.js" -> text(name)
        else -> null
    }
}
